class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        # validity of the window gonna be 
        # the number of '0' within the subarray <= k
        # size 
        ans = 0
        l = 0
        numOfZeros = 0

        for r in range(len(nums)):
            if nums[r] == 0:
                numOfZeros += 1

            while numOfZeros > k:
                if nums[l] == 0:
                    numOfZeros -= 1
                l += 1

            size = (r - l) + 1
            ans = max(ans, size)
        return ans
